fn is_non_prime(n: u64) -> bool {
    // Check for divisors from 2 to the square root of n
    let limit = (n as f64).sqrt() as u64;
    for k in 2..=limit {
        if n % k == 0 {
            return true; // Found a non-trivial divisor
        }
    }
    false // No non-trivial divisors found, n is prime
}